function initBootstrapViewer() {
    getOwnedTableShards();
}

function BootstrapRetry() {
    $.ajax({
        url: "/dbg/bootstrap/retry",
        method: "POST",
        success: function (body) {
            alert(body)
            initBootstrapViewer()
        },
        error: function (xhr) {
            alert(xhr.responseText);
        }
    });
}

function getOwnedTableShards() {
    Promise.all([
        promiseFromAjax({url: '/schema/tables'}),
        promiseFromAjax({url: '/dbg/shards'}),
    ]).then(function ([tables, shards]) {
        Promise.all(tables.map(table =>  {
            return promiseFromAjax({url: '/schema/tables/{0}'.format(table), type:'GET'})
        })).then(function (schemas) {
            Promise.all(schemas.flatMap(function (schema) {
                if (!schema.isFactTable) {
                    return [{table: schema.name, shard: 0}];
                } else {
                    return shards.map(function (shardID) {
                        return {table: schema.name, shard: shardID}
                    });
                }
            }).map(tableShard => {
                return promiseFromAjax({url: '/dbg/{0}/{1}'.format(tableShard.table, tableShard.shard)}, summary => {
                    return {
                        ...tableShard,
                        ...summary,
                    }
                })
            })).then(tableShardSummaries => {
                renderTableShardTable(tableShardSummaries);
            })
        });
    });
}

function renderTableShardTable(tableShardSummaries) {
    function renderBootstrapStatus(data, type, row) {
        const bootstrapStateMap = {
            0: {label: 'Not Started', color: 'red'},
            1: {label: 'Started', color: 'orange'},
            2: {label: 'Bootstrapped', color: 'green'},
        };
        return '<span style="color:'+bootstrapStateMap[data].color+'">'+bootstrapStateMap[data].label+'</span>';
    }

    function renderBootstrapStage(data, type, row) {
        const stageColorMap = {
            waiting:  'red',
            peercopy: 'orangered',
            preload:  'orange',
            recovery: 'yellowgreen',
            finished: 'green',
        };
        return '<span style="color:'+stageColorMap[data]+'">'+data+'</span>';
    }

    function renderProgress(data, type, row) {
        function getStyleClass(percent) {
            if (percent >= 100) {
                return "bg-success"
            } else if (percent >= 60) {
                return "bg-info"
            } else if (percent >= 30) {
                return "bg-warning"
            } else if (percent >= 0) {
                return "bg-danger"
            }
        }

        var percentFinished = 0;
        var numFinishedBatches = 0;
        var numPendingBatches = 0;
        var numColumns = data.numColumns;
        if (data.batches) {
            var pendingBatches = Object.keys(data.batches);
            numPendingBatches = pendingBatches.length;
            if (numPendingBatches > 0) {
                console.log(pendingBatches);
                numFinishedBatches = pendingBatches.map(batchID => {
                    var columnStatus = data.batches[batchID];
                    // if all columns are finished copying then batch is done
                    return columnStatus.filter(status => {return status !== 1}).length === numColumns ? 1 : 0;
                }).reduce((x, y) => x + y);
                percentFinished = numFinishedBatches * 100.0 / numPendingBatches;
            }
        }
        return '<div class="progress"> <div class="progress-bar {0} progress-bar-striped active" role="progressbar" aria-valuenow="{1}" aria-valuemin="0" aria-valuemax="100" style="width:{2}%"> {3} / {4} Batches Copied </div> </div>'.format(getStyleClass(percentFinished), percentFinished, percentFinished, numFinishedBatches, numPendingBatches);
    }

    //TODO(@jshencode)
    //  1. column level tracking
    var tableShardsTable = $('#table-shards-table').DataTable({
        paging: false,
        autoWidth: false,
        aoColumns: [
            {title: "Table", data: "table"},
            {title: "Shard", data: "shard"},
            {title: "Stage", data: "bootstrapDetails.stage", render: renderBootstrapStage},
            {
                title: "StartedAt",
                data: "bootstrapDetails.startedAt",
                render: function (data) {
                    return new Date(data * 1000).toLocaleString()
                }
            },
            {title: "Source", data: "bootstrapDetails.source"},
            {title: "Peer Copy Progress", data: "bootstrapDetails", render: renderProgress},
            {title: "Status", data: "BootstrapState", render: renderBootstrapStatus},
        ],
        aaData: tableShardSummaries
    });

    $('#table-columns-close').click(function(event){
        $('#table-columns').addClass("collapse");
        $("#table-shards").removeClass("col-md-6");
        $("#table-shards").addClass("col-md-12");
    });

    $('#table-shards-table').on('click', 'tr', function(event) {
        var data = tableShardsTable.row(this).data();
        tableColumnsTable.clear();
        tableColumnsTable.rows.add(data.columns).draw();
        $("#table-shards").removeClass("col-md-12");
        $("#table-shards").addClass("col-md-6");
        $('#table-columns').removeClass("collapse");
    });
}

package datanode

import (
	"errors"
	m3Shard "github.com/m3db/m3/src/cluster/shard"
	xerrors "github.com/m3db/m3/src/x/errors"
	"github.com/onsi/ginkgo"
	. "github.com/onsi/gomega"
	"github.com/stretchr/testify/mock"
	aresShard "github.com/uber/aresdb/cluster/shard"
	"github.com/uber/aresdb/cluster/topology"
	"github.com/uber/aresdb/datanode/bootstrap"
	"github.com/uber/aresdb/datanode/bootstrap/mocks"
	"github.com/uber/aresdb/utils"
	"sync"
	"sync/atomic"
	"time"
)

var _ = ginkgo.Describe("bootstrap manager", func() {

	ginkgo.It("bootstrap manager should work", func() {
		mockBootstrapble := &mocks.Bootstrapable{}

		host0 := topology.NewHost("instance0", "http://host0:9374")
		host1 := topology.NewHost("instance1", "http://host1:9374")
		staticMapOption := topology.NewStaticOptions().
			SetReplicas(1).
			SetHostShardSets([]topology.HostShardSet{
				topology.NewHostShardSet(host0, aresShard.NewShardSet([]m3Shard.Shard{
					m3Shard.NewShard(0),
				})),
				topology.NewHostShardSet(host1, aresShard.NewShardSet([]m3Shard.Shard{
					m3Shard.NewShard(0),
				})),
			}).SetShardSet(aresShard.NewShardSet([]m3Shard.Shard{
			m3Shard.NewShard(0),
		}))
		staticTopology, _ := topology.NewStaticInitializer(staticMapOption).Init()
		opts := bootstrap.NewOptions()

		manager := NewBootstrapManager(
			"host1",
			mockBootstrapble,
			opts,
			staticTopology,
		)

		var timer uint32 = 0
		var triggered uint32 = 0

		// 1. test multiple triggering of manager.Bootstrap()
		utils.SetCurrentTime(time.Unix(10, 0))
		defer utils.ResetClockImplementation()

		// bootstrapble only should be triggered twice although manager is triggered 10 times
		// first time when first manager.Bootstrap() is called
		// second time when first bootstrap task is finished and manager detects pending task exists
		mockBootstrapble.On("Bootstrap", mock.Anything, "host1", staticTopology, mock.Anything, opts).Run(func(args mock.Arguments) {
			atomic.AddUint32(&triggered, 1)
			// simulating 10 seconds to finish
			for atomic.LoadUint32(&timer) < 10 {
			}
		}).Return(nil).Twice()

		mutex := &sync.Mutex{}
		errs := xerrors.NewMultiError()
		wg := &sync.WaitGroup{}

		// before run
		Ω(manager.IsBootstrapped()).Should(BeFalse())
		for i := 0; i < 10; i++ {
			wg.Add(1)
			go func() {
				// simulate time increment one sec at a time
				// by the time 10th bootstrap trigger on manager,
				// the first bootstrap task should just finish
				atomic.AddUint32(&timer, 1)
				err := manager.Bootstrap()
				if err != nil {
					mutex.Lock()
					errs = errs.Add(err)
					mutex.Unlock()
				}
				wg.Done()
			}()
		}
		wg.Wait()

		// after run
		Ω(errs.FinalError()).Should(BeNil())
		Ω(triggered).Should(Equal(uint32(2)))
		Ω(manager.IsBootstrapped()).Should(BeTrue())
		t, isBootstapped := manager.LastBootstrapCompletionTime()
		Ω(t).Should(Equal(utils.Now()))
		Ω(isBootstapped).Should(BeTrue())

		// 2. test error case
		mockBootstrapble.On("Bootstrap", mock.Anything, "host1", staticTopology, mock.Anything, opts).
			Return(errors.New("failed to run bootstrap")).Once()

		err := manager.Bootstrap()
		Ω(err).ShouldNot(BeNil())
	})

})

